// ── MODAL LOGIC ───────────────────────────────────────────────────
function scrollToAbout() {
  const target = document.getElementById('about');
  if (!target) return;
  const start = window.scrollY;
  const end = target.getBoundingClientRect().top + start;
  const duration = 900;
  let startTime = null;
  function step(ts) {
    if (!startTime) startTime = ts;
    const elapsed = ts - startTime;
    const t = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - t, 3);
    window.scrollTo(0, start + (end - start) * eased);
    if (t < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

let currentModalId = null;
let visibleProjectIds = [];

function updateVisibleIds() {
  visibleProjectIds = [...document.querySelectorAll('.project-card')]
    .filter(c => c.style.display !== 'none')
    .map(c => { const m = (c.getAttribute('onclick')||'').match(/openModal\('([^']+)'\)/); return m ? m[1] : null; })
    .filter(Boolean);
}

function updateModalNav() {
  const idx = visibleProjectIds.indexOf(currentModalId);
  const prev = document.getElementById('modal-prev');
  const next = document.getElementById('modal-next');
  if (prev) prev.disabled = idx <= 0;
  if (next) next.disabled = idx < 0 || idx >= visibleProjectIds.length - 1;
}

function modalNav(dir) {
  const idx = visibleProjectIds.indexOf(currentModalId);
  if (idx < 0) return;
  const newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= visibleProjectIds.length) return;
  openModal(visibleProjectIds[newIdx]);
  document.getElementById('modal-overlay').scrollTop = 0;
}

function openModal(id) {
  let parentId = id, sectionId = null;
  if (id.includes('__')) { const i = id.indexOf('__'); parentId = id.slice(0,i); sectionId = id.slice(i+2); }
  const p = PROJECTS[parentId];
  if (!p) return;
  currentModalId = id;

  // Merged tags: parent + section (deduped)
  let displayTags = [...(p.tags || [])];
  if (sectionId && p.subprojects) {
    const sub = p.subprojects.find(s => s.id === sectionId);
    if (sub?.tags?.length) displayTags = [...new Set([...displayTags, ...sub.tags])];
  }
  document.getElementById('modal-tags').innerHTML = displayTags.map(t => `<span class="modal-tag">${t}</span>`).join('');
  document.getElementById('modal-title').textContent = p.title;
  document.getElementById('modal-sub').textContent = p.sub || '';
  document.getElementById('modal-header-desc').textContent = p.desc || '';

  const modal = document.getElementById('modal');
  const bodyEl = modal.querySelector('.modal-body, .modal-body-sectioned');

  modal.classList.add('modal-sectioned');
  modal.classList.add('modal-two-col');
  bodyEl.className = 'modal-body modal-body-sectioned';
  renderSectionedModal(p, sectionId, bodyEl);

  document.getElementById('modal-overlay').classList.add('open');
  const _sy = window.scrollY;
  document.body.dataset.scrollY = _sy;
  sessionStorage.setItem('pf_modal', id);
  sessionStorage.setItem('pf_page_sy', String(_sy));
  document.body.style.position = 'fixed';
  document.body.style.top = `-${_sy}px`;
  document.body.style.left = '0';
  document.body.style.right = '0';
  document.body.style.overflow = 'hidden';
  updateModalNav();
}

function secToolIconsHtml(tools) {
  const skillMap = {};
  (window.PORTFOLIO_DATA?.skills || []).forEach(s => { skillMap[s.name] = s; });
  return (tools||[]).map(name => {
    const skill = skillMap[name];
    if (!skill) return '';
    const icon = skill.icon || '';
    const inner = icon.startsWith('http') || icon.startsWith('data/')
      ? `<img src="${icon}" alt="${name}">`
      : `<span>${icon}</span>`;
    return `<span class="sec-tool-icon" title="${name}">${inner}</span>`;
  }).filter(Boolean).join('');
}

function renderSectionedModal(p, sectionId, bodyEl) {
  const sections = [];
  if ((p.images||[]).length) sections.push({ id:'__parent__', title: p.title, images: p.images, coverImage: p.coverImage||'', tools: p.tools||[], ar: p.sectionAspectRatio||'auto', bg: p.bgImage||'', filterTags:'', order:-1 });
  (p.subprojects||[]).forEach(s => sections.push({ id: s.id, title: s.title, images: s.images||[], coverImage: s.coverImage||'', tools: s.tools||[], ar: s.sectionAspectRatio||'auto', bg: s.bgImage||'', filterTags: s.filterTags||'', order: s.order||0 }));

  const _fv = window.PORTFOLIO_DATA?.filterViews||[];
  const _av = _fv.find(v=>v.id===activeViewId||v.tag===activeViewId);
  const _at = _av?.tag||'';
  const _tp = [_at,..._fv.filter(v=>v.id!=='all').map(v=>v.tag).filter(t=>t&&t!==_at)].filter(Boolean);
  const _ss = s => { const tags=(s.filterTags||'').split(' ').filter(Boolean); const i=_tp.findIndex(t=>tags.includes(t)); return i===-1?_tp.length:i; };
  sections.sort((a,b)=>{if(a.id===sectionId)return -1;if(b.id===sectionId)return 1;const d=_ss(a)-_ss(b);return d!==0?d:(a.order||0)-(b.order||0);});
  if (!sectionId || !sections.find(s=>s.id===sectionId)) sectionId = sections[0]?.id || '';

  const hasNav = (p.subprojects||[]).length > 0;

  // Tags
  let displayTags = [...(p.tags || [])];
  if (sectionId && p.subprojects) {
    const sub = p.subprojects.find(s => s.id === sectionId);
    if (sub?.tags?.length) displayTags = [...new Set([...displayTags, ...sub.tags])];
  }
  const tagsHtml = displayTags.map(t => `<span class="modal-tag">${t}</span>`).join('');

  // Chapter nav items with tool icons
  const navItemsHtml = hasNav ? sections.map(s => {
    const toolIcons = secToolIconsHtml(s.tools);
    const toolsSpan = toolIcons ? `<span class="modal-sec-tool-icons">${toolIcons}</span>` : '';
    return `<div class="modal-sec-nav-item${s.id===sectionId?' active':''}" data-sec="${s.id}" onclick="switchSection('${s.id}')" style="--dot-rot:${randRot()}"><span class="nav-dot"></span><span class="nav-item-label">${s.title}</span>${toolsSpan}</div>`;
  }).join('') : '';

  const linkBtn = p.link
    ? `<a href="${p.link.url}" target="_blank" rel="noopener" class="proj-btn proj-btn-primary" style="text-decoration:none;">${p.link.label}</a>`
    : '';
  const linkDesktop = linkBtn ? `<div class="modal-link-wrap modal-link-desktop">${linkBtn}</div>` : '';
  const linkMobile  = linkBtn ? `<div class="modal-link-wrap modal-link-mobile">${linkBtn}</div>`  : '';

  const leftPanel = `<div class="modal-left-panel">
    <button class="modal-close" onclick="closeModalBtn()"></button>
    <div class="modal-left-inner">
      ${tagsHtml ? `<div class="modal-tags">${tagsHtml}</div>` : ''}
      <div class="modal-left-title">${p.title||''}</div>
      ${p.sub ? `<div class="modal-left-sub">${p.sub}</div>` : ''}
      ${p.desc ? `<p class="modal-left-desc">${p.desc}</p>` : ''}
      ${hasNav ? `<p class="modal-chapters-label">Chapters</p><div class="modal-sec-nav-items">${navItemsHtml}</div>` : ''}
      ${linkDesktop}
    </div>
  </div>`;

  const contentHtml = sections.map(s => {
    const toolIcons = secToolIconsHtml(s.tools);
    const arPart  = s.ar && s.ar !== 'auto' ? `aspect-ratio:${s.ar};object-fit:contain;` : '';
    const bgSrc   = s.bg ? resolveImageSrc(s.bg) : '';
    const _bgIsGrad = bgSrc.startsWith('linear-gradient') || bgSrc.startsWith('radial-gradient');
    const bgPart  = bgSrc ? (_bgIsGrad ? `background:${bgSrc};` : `background:url(${bgSrc}) center/cover no-repeat;`) : (arPart ? 'background:rgba(0,0,0,.03);' : '');
    const cellBgFull = bgSrc ? (_bgIsGrad ? `background:${bgSrc};` : `background:url(${bgSrc}) center/cover no-repeat;`) : '';
    // pair cells: fixed aspect-ratio (uses section ar, defaults to 3/2) so both halves have the same height
    const pairAr   = (s.ar && s.ar !== 'auto') ? s.ar : '3/2';
    const pairCell = (src, t) => {
      if (!src) return '';
      const pSrc = previewSrc(src);
      const thisCellBg = _isPng(src) ? cellBgFull : '';
      const inner = _isVideo(src)
        ? `<video src="${src}" controls playsinline loop onclick="event.stopPropagation()" style="width:100%;height:auto;display:block;"></video>`
        : `<img src="${pSrc}" alt="${t}" onclick="openLightbox('${src}')" style="width:100%;height:auto;display:block;"${pSrc !== src ? ` onerror="this.onerror=null;this.src='${src}'"` : ''}>`;
      return `<div class="modal-pair-cell" style="${thisCellBg}">${inner}</div>`;
    };
    const imgs = s.images.filter(key => key !== s.coverImage && key !== s.bg).flatMap(key => {
      if (key.includes('||')) {
        const [a, b] = key.split('||');
        const sA = resolveImageSrc(a), sB = resolveImageSrc(b);
        if (!sA && !sB) return [];
        return [`<div class="modal-img-pair">${pairCell(sA,s.title)}${pairCell(sB,s.title)}</div>`];
      }
      const src = resolveImageSrc(key); if (!src) return [];
      if (_isVideo(src)) return [`<video class="modal-video" src="${src}" controls playsinline loop onclick="event.stopPropagation()"></video>`];
      const pSrc = previewSrc(src);
      const hasPreview = pSrc !== src;
      const imgBg = _isPng(src) ? bgPart : '';
      const imgStyle = (arPart || imgBg) ? ` style="${arPart}${imgBg}"` : '';
      return [`<img src="${hasPreview ? pSrc : src}" alt="${s.title}"${imgStyle} onclick="openLightbox('${src}')"${hasPreview ? ` onerror="this.onerror=null;this.src='${src}'"` : ''}>`];
    }).join('');
    const headerInner = `<span class="modal-sec-block-title">${s.title}</span>` +
                        (toolIcons ? `<span class="modal-sec-tool-icons">${toolIcons}</span>` : '');
    const blockHeader = hasNav ? `<div class="modal-sec-block-header">${headerInner}</div>` : '';
    return `<div class="modal-sec-block" id="sec-${s.id}">${blockHeader}<div class="modal-sec-images">${imgs}</div></div>`;
  }).join('');

  bodyEl.innerHTML = `${leftPanel}<div class="modal-sec-content" id="modal-sec-content">${contentHtml}</div>${linkMobile}`;
  bodyEl.querySelectorAll('.modal-img-pair').forEach(equalizePairCells);

  const _sc = document.getElementById('modal-sec-content');
  if (_sc) _sc.scrollTop = 0;
  document.getElementById('modal-overlay').scrollTop = 0;
  document.querySelector('.modal-left-panel')?.classList.remove('collapsed');
  requestAnimationFrame(() => {
    const block = document.getElementById(`sec-${sectionId}`);
    const content = document.getElementById('modal-sec-content');
    if (block && content) {
      const top = block.getBoundingClientRect().top - content.getBoundingClientRect().top + content.scrollTop;
      content.scrollTop = Math.max(0, top - 20);
    }
    setupSectionScrollSpy();
  });
}

let _secScrollLock = false, _secScrollTimer = null;

function switchSection(secId) {
  const block = document.getElementById(`sec-${secId}`);
  const content = document.getElementById('modal-sec-content');
  if (block && content) {
    const top = block.getBoundingClientRect().top - content.getBoundingClientRect().top + content.scrollTop;
    _secScrollLock = true;
    clearTimeout(_secScrollTimer);
    _secScrollTimer = setTimeout(() => { _secScrollLock = false; }, 700);
    content.scrollTo({ top: Math.max(0, top - 20), behavior: 'smooth' });
  }
  document.querySelectorAll('.modal-sec-nav-item').forEach(item => item.classList.toggle('active', item.dataset.sec === secId));
}

function navSection(dir) {
  const items = [...document.querySelectorAll('.modal-sec-nav-item')];
  if (!items.length) return;
  const activeIdx = items.findIndex(i => i.classList.contains('active'));
  const newIdx = Math.max(0, Math.min(items.length - 1, (activeIdx < 0 ? 0 : activeIdx) + dir));
  if (newIdx !== activeIdx) switchSection(items[newIdx].dataset.sec);
}

function setupSectionScrollSpy() {
  const content = document.getElementById('modal-sec-content');
  if (!content) return;
  content.addEventListener('scroll', () => {
    // Collapse header on mobile when user starts scrolling
    if (window.innerWidth <= 768) {
      const panel = document.querySelector('.modal-left-panel');
      if (panel) panel.classList.toggle('collapsed', content.scrollTop > 40);
    }
    // Section scroll spy
    if (_secScrollLock) return;
    const blocks = [...content.querySelectorAll('.modal-sec-block')];
    let current = blocks[0]?.id?.replace('sec-','') || '';
    const contentTop = content.getBoundingClientRect().top;
    for (const block of blocks) {
      if (block.getBoundingClientRect().top - contentTop <= 80) current = block.id.replace('sec-','');
    }
    document.querySelectorAll('.modal-sec-nav-item').forEach(item => item.classList.toggle('active', item.dataset.sec === current));
    sessionStorage.setItem('pf_modal_sy', String(content.scrollTop));
  }, { passive: true });
}

function closeModal(e) {
  if (e.target === document.getElementById('modal-overlay')) closeModalBtn();
}
function closeModalBtn() {
  const modal = document.getElementById('modal');
  document.getElementById('modal-overlay').classList.remove('open');
  const _sy = parseInt(document.body.dataset.scrollY || '0');
  document.body.style.position = '';
  document.body.style.top = '';
  document.body.style.left = '';
  document.body.style.right = '';
  document.body.style.overflow = '';
  window.scrollTo(0, _sy);
  sessionStorage.removeItem('pf_modal');
  sessionStorage.removeItem('pf_page_sy');
  sessionStorage.removeItem('pf_modal_sy');
  modal?.classList.remove('modal-sectioned');
  modal?.classList.remove('modal-two-col');
}

// ── LIGHTBOX ──────────────────────────────────────────────────────
function _isVideo(src) { return /\.(mp4|webm|ogg)$/i.test(src); }
function _isPng(src) { return /\.png(\?|$)/i.test(src); }

let _lbS = 1, _lbTx = 0, _lbTy = 0, _lbFitS = 1;
let _lbDrag = null, _lbMoved = false, _lbPinchDist = null;

function openLightbox(src) {
  const img = document.getElementById('lightbox-img');
  const vid = document.getElementById('lightbox-video');
  const toolbar = document.getElementById('lb-toolbar');
  if (_isVideo(src)) {
    img.style.display = 'none';
    if (toolbar) toolbar.style.display = 'none';
    vid.style.display = '';
    vid.src = src;
    vid.play().catch(() => {});
  } else {
    vid.style.display = 'none'; vid.pause(); vid.src = '';
    img.style.display = '';
    if (toolbar) toolbar.style.display = 'flex';
    img.style.transform = '';
    img.src = src;
    const doFit = () => { if (img.naturalWidth) _lbFit(); };
    img.onload = doFit;
    if (img.complete && img.naturalWidth) doFit();
  }
  document.getElementById('lightbox').classList.add('open');
}

function closeLightbox() {
  document.getElementById('lightbox').classList.remove('open');
  const vid = document.getElementById('lightbox-video');
  if (vid) { vid.pause(); vid.src = ''; }
  _lbDrag = null; _lbPinchDist = null;
}

function _lbFit() {
  const img = document.getElementById('lightbox-img');
  if (!img || !img.naturalWidth) return;
  const lb = document.getElementById('lightbox');
  const VW = lb.clientWidth, VH = lb.clientHeight;
  const W = img.naturalWidth, H = img.naturalHeight;
  _lbFitS = Math.min(VW * 0.92 / W, VH * 0.92 / H);
  _lbS = _lbFitS;
  _lbTx = (VW - W * _lbFitS) / 2;
  _lbTy = (VH - H * _lbFitS) / 2;
  _lbApply();
}

function _lbZoom1x() {
  const img = document.getElementById('lightbox-img');
  if (!img || !img.naturalWidth) return;
  const lb = document.getElementById('lightbox');
  _lbS = 1;
  _lbTx = (lb.clientWidth - img.naturalWidth) / 2;
  _lbTy = (lb.clientHeight - img.naturalHeight) / 2;
  _lbApply();
}

function _lbToggle1x(e) {
  if (Math.abs(_lbS - _lbFitS) < 0.01) {
    const lb = document.getElementById('lightbox');
    const rect = lb.getBoundingClientRect();
    const mx = e.clientX - rect.left, my = e.clientY - rect.top;
    const newS = 1;
    _lbTx = mx - (mx - _lbTx) * (newS / _lbS);
    _lbTy = my - (my - _lbTy) * (newS / _lbS);
    _lbS = newS;
    _lbApply();
  } else {
    _lbFit();
  }
}

function _lbZoomStep(dir) {
  const factor = dir > 0 ? 1.4 : 1 / 1.4;
  const lb = document.getElementById('lightbox');
  const mx = lb.clientWidth / 2, my = lb.clientHeight / 2;
  _lbZoomAt(mx, my, factor);
}

function _lbZoomAt(mx, my, factor) {
  const newS = Math.max(_lbFitS * 0.5, Math.min(10, _lbS * factor));
  _lbTx = mx - (mx - _lbTx) * (newS / _lbS);
  _lbTy = my - (my - _lbTy) * (newS / _lbS);
  _lbS = newS;
  _lbApply();
}

function _lbApply() {
  const img = document.getElementById('lightbox-img');
  if (!img) return;
  img.style.transform = `translate(${_lbTx}px,${_lbTy}px) scale(${_lbS})`;
  const lvl = document.getElementById('lb-zoom-level');
  if (lvl) lvl.textContent = `${Math.round(_lbS * 100)}%`;
  const stage = document.getElementById('lb-stage');
  if (stage) stage.classList.toggle('lb-zoomed', _lbS > _lbFitS + 0.01);
}

function _lbOnWheel(e) {
  if (!document.getElementById('lightbox').classList.contains('open')) return;
  const img = document.getElementById('lightbox-img');
  if (!img || img.style.display === 'none') return;
  e.preventDefault();
  const lb = document.getElementById('lightbox');
  const rect = lb.getBoundingClientRect();
  _lbZoomAt(e.clientX - rect.left, e.clientY - rect.top, e.deltaY < 0 ? 1.12 : 1 / 1.12);
}

function _lbOnMouseDown(e) {
  if (!document.getElementById('lightbox').classList.contains('open')) return;
  const img = document.getElementById('lightbox-img');
  if (!img || img.style.display === 'none') return;
  if (e.button !== 0) return;
  e.preventDefault();
  _lbDrag = { x: e.clientX, y: e.clientY, tx: _lbTx, ty: _lbTy };
  _lbMoved = false;
  document.getElementById('lb-stage')?.classList.add('lb-dragging');
}

function _lbOnMouseMove(e) {
  if (!_lbDrag) return;
  const dx = e.clientX - _lbDrag.x, dy = e.clientY - _lbDrag.y;
  if (Math.abs(dx) > 3 || Math.abs(dy) > 3) _lbMoved = true;
  _lbTx = _lbDrag.tx + dx; _lbTy = _lbDrag.ty + dy;
  _lbApply();
}

function _lbOnMouseUp(e) {
  const wasDrag = _lbMoved;
  _lbDrag = null; _lbMoved = false;
  document.getElementById('lb-stage')?.classList.remove('lb-dragging');
  if (!wasDrag && Math.abs(_lbS - _lbFitS) < 0.01) closeLightbox();
}

function _lbOnTouchStart(e) {
  if (!document.getElementById('lightbox').classList.contains('open')) return;
  if (e.touches.length === 2) {
    const [t0, t1] = e.touches;
    _lbPinchDist = Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);
    _lbDrag = null; e.preventDefault();
  } else if (e.touches.length === 1) {
    _lbDrag = { x: e.touches[0].clientX, y: e.touches[0].clientY, tx: _lbTx, ty: _lbTy };
    _lbMoved = false;
  }
}

function _lbOnTouchMove(e) {
  if (!document.getElementById('lightbox').classList.contains('open')) return;
  if (e.touches.length === 2 && _lbPinchDist) {
    const [t0, t1] = e.touches;
    const dist = Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);
    const mx = (t0.clientX + t1.clientX) / 2, my = (t0.clientY + t1.clientY) / 2;
    const lb = document.getElementById('lightbox');
    const rect = lb.getBoundingClientRect();
    _lbZoomAt(mx - rect.left, my - rect.top, dist / _lbPinchDist);
    _lbPinchDist = dist; e.preventDefault();
  } else if (e.touches.length === 1 && _lbDrag) {
    const dx = e.touches[0].clientX - _lbDrag.x, dy = e.touches[0].clientY - _lbDrag.y;
    if (Math.abs(dx) > 5 || Math.abs(dy) > 5) _lbMoved = true;
    _lbTx = _lbDrag.tx + dx; _lbTy = _lbDrag.ty + dy;
    _lbApply(); e.preventDefault();
  }
}

function _lbOnTouchEnd(e) {
  _lbPinchDist = null;
  if (_lbDrag && !_lbMoved && Math.abs(_lbS - _lbFitS) < 0.01) closeLightbox();
  _lbDrag = null;
}

// ── Pair cell equalization ────────────────────────────────────────
function equalizePairCells(pair) {
  const cells = [...pair.querySelectorAll(':scope > .modal-pair-cell')];
  if (cells.length !== 2) return;
  const getEl = c => c.querySelector('img, video');
  const elA = getEl(cells[0]), elB = getEl(cells[1]);
  if (!elA || !elB) return;
  const getRatio = el => new Promise(resolve => {
    const read = () => el.tagName === 'VIDEO'
      ? (el.videoWidth && el.videoHeight ? el.videoWidth / el.videoHeight : 0)
      : (el.naturalWidth && el.naturalHeight ? el.naturalWidth / el.naturalHeight : 0);
    const v = read(); if (v) { resolve(v); return; }
    // No error listener: if preview fails, onerror on the element changes src to original,
    // which fires a new load event — this listener catches that too.
    el.addEventListener(el.tagName === 'VIDEO' ? 'loadedmetadata' : 'load', () => resolve(read()), { once: true });
  });
  Promise.all([getRatio(elA), getRatio(elB)]).then(([rA, rB]) => {
    if (!rA || !rB) return;
    cells[0].style.flex = rA;
    cells[1].style.flex = rB;
  });
}

// ── FILTER ────────────────────────────────────────────────────────
function getCardId(card) {
  const m = (card.getAttribute('onclick')||'').match(/openModal\('([^']+)'\)/);
  return m ? m[1] : null;  // may be 'id' or 'parentId__subId' — both work for nav
}
function getCardMap(cards) {
  const map = {};
  cards.forEach(c => { const id = getCardId(c); if (id) map[id] = c; });
  return map;
}

function applyViewSettings() {
  const grid = document.getElementById('projects-grid');
  if (!grid) return;
  const isDesktop = window.innerWidth > 900;
  const gs = window.PORTFOLIO_DATA?.gridSettings || {};
  if (isDesktop) {
    grid.style.gridTemplateColumns = `repeat(${gs.columns||6},1fr)`;
    const [w,h] = (gs.aspectRatio||'3/2').split('/').map(Number);
    document.querySelectorAll('.project-card').forEach(card => {
      if (card.classList.contains('vertical')) return;
      const span = card.classList.contains('wide')?3:card.classList.contains('featured')?2:1;
      card.style.aspectRatio = `${w*span}/${h}`;
    });
  } else {
    grid.style.gridTemplateColumns = '';
    document.querySelectorAll('.project-card').forEach(card => {
      card.style.aspectRatio = '';
    });
  }
}
window.addEventListener('resize', applyViewSettings, { passive: true });

function randRot() { return Math.round((Math.random()-0.5)*90)+'deg'; }

function renderFilterBar() {
  const sidebar = document.getElementById('filter-sidebar');
  if (!sidebar) return;
  const views = window.PORTFOLIO_DATA?.filterViews;
  if (!views || !views.length) return;
  const allCards = [...document.querySelectorAll('.project-card')];
  const visibleViews = views.filter(v => {
    if (!v.label?.trim() || v.visible === false) return false;
    if (v.id === 'all') return allCards.some(c => c.dataset.selection === 'true');
    return v.tag && allCards.some(c => (c.dataset.tags || '').split(' ').includes(v.tag));
  });
  sidebar.innerHTML = visibleViews.map((v,i) =>
    `<button class="filter-btn${i===0?' active':''}" data-viewid="${v.id}" onclick="filterByView('${v.id}',this)" style="--dot-rot:${randRot()}">${v.label}</button>`
  ).join('');
}

function filterByView(viewId, btn) {
  activeViewId = viewId;
  document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const views = window.PORTFOLIO_DATA?.filterViews || [];
  const view = views.find(v => v.id === viewId) || {id:viewId,tag:viewId,projectOrder:[]};

  const grid = document.getElementById('projects-grid');
  if (!grid) return;
  grid.style.opacity = '0';
  const allCards = [...grid.querySelectorAll('.project-card')];
  const cardMap = getCardMap(allCards);

  if (viewId === 'all') {
    // If a recruiter focus profile is active, use its filterView projectOrder
    let order = [];
    if (activeFocus) {
      const fv = views.find(v=>v.tag===activeFocus||v.id===activeFocus);
      if (fv?.projectOrder?.length) order = fv.projectOrder;
    }
    if (!order.length) order = view.projectOrder||[];

    if (order.length) {
      // Respect the saved order for ordered+selected cards, then append remaining selected cards
      order.forEach(id => { if (cardMap[id] && cardMap[id].dataset.selection==='true') grid.appendChild(cardMap[id]); });
      allCards.forEach(c => { const id=getCardId(c); if (c.dataset.selection==='true' && !order.includes(id)) grid.appendChild(c); });
    }
    // data-selection is always the visibility gate
    allCards.forEach(c => { c.style.display=c.dataset.selection==='true'?'':'none'; });
  } else {
    const order = view.projectOrder||[];
    if (order.length) order.forEach(id => { if (cardMap[id]) grid.appendChild(cardMap[id]); });
    allCards.forEach(c => { c.style.display=c.dataset.tags.includes(view.tag)?'':'none'; });
  }

  // Apply per-view card sizes (set in admin per view)
  const cardSizes = view.cardSizes || {};
  allCards.forEach(c => {
    const id = getCardId(c); if (!id) return;
    c.classList.remove('featured', 'wide', 'vertical');
    const cs = cardSizes[id];
    if (cs === 'featured') c.classList.add('featured');
    else if (cs === 'wide') c.classList.add('wide');
  });

  applyViewSettings();
  updateVisibleIds();
  grid.style.opacity = '1';
  requestAnimationFrame(() => { grid.style.opacity = '1'; });
}

// backward-compat alias
function filterProjects(tag, btn) { filterByView(tag, btn); }

// ── SMOOTH SCROLL ─────────────────────────────────────────────────
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const t = document.querySelector(a.getAttribute('href'));
    if (t) { e.preventDefault(); t.scrollIntoView({behavior:'smooth'}); }
  });
});


