function applyFocusProfile() {
  const params = new URLSearchParams(window.location.search);
  const focus = params.get('focus');
  if (!focus) return;

  // Use filterViews as source of truth, fall back to hardcoded FOCUS_PROFILES
  const view = (window.PORTFOLIO_DATA?.filterViews||[]).find(v=>v.tag===focus);
  const fp = FOCUS_PROFILES[focus];
  if (!view && !fp) return;

  activeFocus = focus;
  activeViewId = view?.id || focus;
  const label = view?.label || fp?.label || focus;
  const order = (view?.projectOrder?.length ? view.projectOrder : null) || fp?.order || [];

  const grid = document.getElementById('projects-grid');
  if (!grid) return;
  const cards = Array.from(grid.querySelectorAll('.project-card'));
  const cardMap = getCardMap(cards);

  const ordered = order.filter(id=>cardMap[id]).map(id=>cardMap[id]);
  cards.forEach(c => { if (!ordered.includes(c)) ordered.push(c); });
  ordered.forEach(c => grid.appendChild(c));

  showFocusBadge(label, focus);
  updateHeroTagline(label);
}

function showFocusBadge(label, focus) {
  const badge = document.createElement('div');
  badge.id = 'focus-badge';
  badge.style.cssText = `
    position: fixed; bottom: 20px; right: 20px; z-index: 9999;
    background: rgba(61,31,92,0.92); color: #C9922B;
    font-family: 'DM Mono', monospace; font-size: 10px;
    letter-spacing: 0.15em; text-transform: uppercase;
    padding: 8px 14px; border-radius: 2px;
    border: 1px solid rgba(201,146,43,0.3);
    backdrop-filter: blur(8px);
    opacity: 0; transition: opacity 0.5s;
    pointer-events: none;
  `;
  badge.textContent = '⚡ ' + label + ' view';
  document.body.appendChild(badge);
  // Appare brevemente poi svanisce
  setTimeout(() => { badge.style.opacity = '1'; }, 300);
  setTimeout(() => { badge.style.opacity = '0'; }, 3000);
  setTimeout(() => { badge.remove(); }, 3600);
}

function updateHeroTagline(label) {
  const tagline = document.querySelector('.tag-line');
  if (tagline) {
    tagline.textContent = label + ' · Available for hire';
  }
}

// Genera URL personalizzato (utility per copiare link)
function generateFocusURL(focus) {
  const url = new URL(window.location.href.split('?')[0]);
  url.searchParams.set('focus', focus);
  return url.toString();
}

// Panel nascosto — Shift+P per aprire
let panelOpen = false;
document.addEventListener('keydown', e => {
  if (e.shiftKey && e.key === 'P') {
    e.preventDefault();
    toggleSharePanel();
  }
});

function toggleSharePanel() {
  const existing = document.getElementById('share-panel');
  if (existing) { existing.remove(); panelOpen = false; return; }
  panelOpen = true;

  const panel = document.createElement('div');
  panel.id = 'share-panel';
  panel.style.cssText = `
    position: fixed; top: 50%; left: 50%; transform: translate(-50%,-50%);
    z-index: 9999; background: #1A1225; border: 1px solid rgba(201,146,43,0.3);
    border-radius: 4px; padding: 36px; min-width: 420px; max-width: 90vw;
    box-shadow: 0 24px 80px rgba(0,0,0,0.6);
    font-family: 'DM Sans', sans-serif;
  `;

  const PROFILE_ICONS = {concept:'✏️',character:'🧙',creature:'🐉',vfx:'✨',weapon:'⚔️','3d':'🔷',environment:'🌲',fortnite:'🎯',roblox:'🎮',illustration:'🎨',animation:'🎬'};
  const fViews = (window.PORTFOLIO_DATA?.filterViews||[]).filter(v=>v.id!=='all'&&v.tag&&v.tag!=='all');
  const profiles = (fViews.length ? fViews : [
    {tag:'concept',label:'Concept Artist'},
    {tag:'character',label:'Character Designer'},
    {tag:'creature',label:'Creature Designer'},
    {tag:'vfx',label:'VFX Concept Artist'},
    {tag:'3d',label:'3D Generalist'},
    {tag:'fortnite',label:'Fortnite / UEFN Artist'},
    {tag:'roblox',label:'Roblox Artist'},
    {tag:'illustration',label:'Illustrator'},
  ]).map(v => ({ key: v.tag||v.id, icon: PROFILE_ICONS[v.tag]||'📁', label: v.label, tags: [v.tag||v.id] }));

  let inner = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <div>
        <div style="font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.2em;color:#C9922B;text-transform:uppercase;margin-bottom:6px;">Recruiter Link Generator</div>
        <div style="font-family:'Playfair Display',serif;font-size:22px;color:#fff;font-weight:700;">Scegli il profilo</div>
      </div>
      <button onclick="document.getElementById('share-panel').remove();document.getElementById('share-overlay').remove();panelOpen=false;" style="background:rgba(255,255,255,.08);border:none;color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px;">✕</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:20px;">
  `;

  profiles.forEach(p => {
    const chips = p.tags.map(t => `<span style="font-size:9px;background:rgba(201,146,43,.18);color:#C9922B;padding:2px 6px;border-radius:2px;letter-spacing:.06em;font-family:'DM Mono',monospace;">#${t}</span>`).join('');
    inner += `
      <button onclick="copyFocusLink('${p.key}', this)" style="
        background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);
        border-radius:3px;padding:12px 14px;text-align:left;cursor:pointer;
        transition:all .2s;color:#fff;
      " onmouseover="this.style.borderColor='#C9922B'" onmouseout="this.style.borderColor='rgba(255,255,255,.1)'">
        <div style="font-size:18px;margin-bottom:6px;">${p.icon}</div>
        <div style="font-size:13px;font-weight:600;margin-bottom:7px;">${p.label}</div>
        <div style="display:flex;flex-wrap:wrap;gap:3px;">${chips}</div>
      </button>
    `;
  });

  inner += `</div>
    <div id="copied-url" style="display:none;background:rgba(201,146,43,.1);border:1px solid rgba(201,146,43,.3);border-radius:3px;padding:12px 14px;margin-bottom:12px;">
      <div style="font-family:'DM Mono',monospace;font-size:9px;color:#C9922B;letter-spacing:.15em;margin-bottom:6px;">URL COPIATO ✓</div>
      <div id="copied-url-text" style="font-size:12px;color:rgba(255,255,255,.7);word-break:break-all;"></div>
    </div>
    <div style="font-family:'DM Mono',monospace;font-size:9px;color:rgba(255,255,255,.25);letter-spacing:.1em;text-align:center;">
      SHIFT+P per chiudere · Click su un profilo per copiare il link
    </div>
  `;

  panel.innerHTML = inner;

  // Overlay scuro dietro
  const overlay = document.createElement('div');
  overlay.id = 'share-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9998;';
  overlay.onclick = () => { panel.remove(); overlay.remove(); panelOpen = false; };

  document.body.appendChild(overlay);
  document.body.appendChild(panel);
}

function copyFocusLink(focus, btn) {
  // In locale usa window.location, su GitHub Pages usa l'URL reale
  const base = window.location.href.split('?')[0].split('#')[0];
  const url = base + '?focus=' + focus;
  
  navigator.clipboard.writeText(url).then(() => {
    const box = document.getElementById('copied-url');
    const txt = document.getElementById('copied-url-text');
    if (box && txt) {
      txt.textContent = url;
      box.style.display = 'block';
    }
    const orig = btn.style.borderColor;
    btn.style.borderColor = '#C9922B';
    btn.style.background = 'rgba(201,146,43,.1)';
    setTimeout(() => {
      btn.style.borderColor = 'rgba(255,255,255,.1)';
      btn.style.background = 'rgba(255,255,255,.04)';
    }, 1500);
  }).catch(() => {
    // Fallback per browser che non supportano clipboard API
    const box = document.getElementById('copied-url');
    const txt = document.getElementById('copied-url-text');
    if (box && txt) {
      txt.textContent = url + ' (copia manualmente)';
      box.style.display = 'block';
    }
  });
}

// ── DYNAMIC RENDERING ─────────────────────────────────────────────────────────

function resolveImageSrc(key) {
  if (!key) return '';
  if (key.startsWith('data/images/')) return key;
  if (key.startsWith('linear-gradient') || key.startsWith('radial-gradient')) return key;
  return IMGS[key] || '';
}
function thumbSrc(path) {
  if (!path || !path.startsWith('data/images/') || path.includes('||') || _isVideo(path)) return path;
  return path.replace(/(\.[^.]+)$/, '_thumb$1');
}
function previewSrc(path) {
  if (!path || !path.startsWith('data/images/') || path.includes('||') || _isVideo(path)) return path;
  return path.replace(/(\.[^.]+)$/, '_preview$1');
}

function renderProjects(pd) {
  Object.keys(PROJECTS).forEach(k => delete PROJECTS[k]);
  CARD_PROJECT_MAP = {};
  pd.forEach((p, i) => {
    PROJECTS[p.id] = {
      title: p.title, sub: p.sub, tags: p.tags, desc: p.description,
      images: p.images || [], coverImage: p.coverImage || '',
      tools: p.tools || [], link: p.link,
      sectionAspectRatio: p.sectionAspectRatio || null,
      bgImage: p.bgImage || '',
      subprojects: (p.subprojects || []).filter(s => s.visible !== false)
    };
    CARD_PROJECT_MAP[p.id] = i;
  });

  const grid = document.getElementById('projects-grid');
  if (!grid) return;
  const cards = [];
  pd.forEach(p => {
    const visibleSubs = (p.subprojects || []).filter(s => s.visible !== false);
    const showAsSubs = visibleSubs.length > 0 && p.inSelection === false;
    if (showAsSubs) {
      [...visibleSubs]
        .sort((a,b) => (a.order||0) - (b.order||0))
        .forEach(sub => {
          const cid = `${p.id}__${sub.id}`;
          const cover = resolveImageSrc(sub.coverImage) || resolveImageSrc((sub.images||[])[0]);
          const subName = `<span class="card-name-main">${p.title}</span><span class="card-name-sep"> : </span><span class="card-name-sub">${sub.title}</span>`;
          const bottom = `<div class="project-bottom"><div class="project-name">${subName}</div>${sub.description ? `<div class="project-desc">${sub.description}</div>` : ''}</div>`;
          cards.push(`<div class="project-card" data-tags="${sub.filterTags||''}" data-selection="${sub.inSelection !== false}" onclick="openModal('${cid}')">
            ${cover ? `<img class="project-thumb" src="${thumbSrc(cover)}" onerror="this.onerror=null;this.src='${cover}'" alt="${sub.title}" loading="lazy">` : ''}
            <canvas class="card-wave-canvas"></canvas>
            <div class="project-overlay">${bottom}</div>
          </div>`);
        });
    } else {
      const cover = resolveImageSrc(p.coverImage);
      const linkBtn = p.link ? `<a class="proj-btn proj-btn-outline" href="${p.link.url}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${p.link.label}</a>` : '';
      const bottomInner = `<div class="project-name">${p.title}</div>${p.cardDesc?`<div class="project-desc">${p.cardDesc}</div>`:''}${linkBtn?`<div class="project-actions">${linkBtn}</div>`:''}`;
      cards.push(`<div class="project-card" data-tags="${p.filterTags}" data-selection="true" onclick="openModal('${p.id}')">
        ${cover ? `<img class="project-thumb" src="${thumbSrc(cover)}" onerror="this.onerror=null;this.src='${cover}'" alt="${p.title}" loading="lazy">` : ''}
        <canvas class="card-wave-canvas"></canvas>
        <div class="project-overlay"><div class="project-bottom">${bottomInner}</div></div>
      </div>`);
    }
  });
  grid.innerHTML = cards.join('');
  initCardWaves();
  filterByView(activeViewId || 'all');
}

function initCardWaves() {
  document.querySelectorAll('.project-card').forEach(card => {
    const canvas = card.querySelector('.card-wave-canvas');
    if (!canvas || canvas._waveInit) return;
    canvas._waveInit = true;

    let destroyWave = null;
    let baseY = 1.25;
    let animRaf = null;

    function animateTo(target, duration, onDone) {
      const from = baseY;
      const t0 = performance.now();
      if (animRaf) cancelAnimationFrame(animRaf);
      function step(now) {
        const p = Math.min(1, (now - t0) / duration);
        const e = p < 0.5 ? 2 * p * p : -1 + (4 - 2 * p) * p;
        baseY = from + (target - from) * e;
        if (p < 1) { animRaf = requestAnimationFrame(step); }
        else { baseY = target; animRaf = null; if (onDone) onDone(); }
      }
      animRaf = requestAnimationFrame(step);
    }

    card.addEventListener('mouseenter', () => {
      if (!destroyWave) {
        destroyWave = WaveEffect.init(canvas, {
          baseY:      () => baseY,
          colorTop:   'rgba(106,58,167,0.80)',
          colorBot:   'rgba(106,58,167,0.40)',
          wind:       0.18,
          flowSpeed:  0.5,
          spawnRate:  2.0,
          tiltGain:   0
        });
      }
      animateTo(0.84, 440);
    });

    card.addEventListener('mouseleave', () => {
      animateTo(1.3, 340, () => {
        if (destroyWave) { destroyWave(); destroyWave = null; }
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        baseY = 1.25;
      });
    });
  });
}

function startYear(str) {
  const m = String(str || '').match(/\d{4}/);
  return m ? parseInt(m[0], 10) : 0;
}

function renderCareer(cd, pd) {
  const careerEl = document.querySelector('.exp-col:first-child .timeline');
  if (careerEl) {
    const sorted = [...cd].sort((a, b) => startYear(b.period) - startYear(a.period));
    careerEl.innerHTML = sorted.map(c => `
      <div class="timeline-item">
        <div class="timeline-dot"></div>
        <div class="timeline-period">${c.period}</div>
        <div class="timeline-role">${c.role}</div>
        <div class="timeline-org">${c.company}</div>
        <ul class="timeline-bullets">
          ${c.bullets.map(b => `<li>${b}</li>`).join('')}
        </ul>
      </div>`).join('');
  }

  const tlEl = document.querySelector('.timeline-mirror');
  if (tlEl) {
    tlEl.innerHTML = (pd || []).filter(p => p.showInTimeline)
      .sort((a, b) => startYear(b.date) - startYear(a.date))
      .map(p => {
      const cls = p.status === 'released' ? 'status-released'
                : p.status === 'unreleased' ? 'status-unreleased'
                : 'status-wip';
      const label = p.status === 'wip' ? 'WIP'
                  : p.status.charAt(0).toUpperCase() + p.status.slice(1);
      return `<div class="timeline-item">
        <div class="timeline-dot proj-dot"></div>
        <div class="timeline-period">${p.date}</div>
        <div class="timeline-role">${p.title} <span class="status-badge ${cls}">${label}</span></div>
        <div class="timeline-org">${p.team}</div>
      </div>`;
    }).join('');
  }
}

