function applySiteContent(sc) {
  function set(id, val) {
    const el = document.getElementById(id);
    if (el && val != null) el.innerHTML = val;
  }
  set('hero-tagline',    sc.hero_tagline);
  set('hero-desc',       sc.hero_desc);
  set('hero-stat1-num',  sc.hero_stat1_num);
  set('hero-stat1-label',sc.hero_stat1_label);
  set('hero-stat2-num',  sc.hero_stat2_num);
  set('hero-stat2-label',sc.hero_stat2_label);
  set('hero-stat3-num',  sc.hero_stat3_num);
  set('hero-stat3-label',sc.hero_stat3_label);
  set('hero-stat4-num',  sc.hero_stat4_num);
  set('hero-stat4-label',sc.hero_stat4_label);
  set('about-p1',        sc.about_p1);
  set('about-p2',        sc.about_p2);
  set('about-p3',        sc.about_p3);
  set('skills-subtitle', sc.skills_subtitle);
  set('contact-label',   sc.contact_label);
  set('contact-heading', sc.contact_heading);
  set('contact-subtitle',sc.contact_subtitle);
  set('footer-note',     sc.footer_note);
}

function renderSocials(socials) {
  const el = document.getElementById('contact-links');
  if (!el || !socials) return;
  el.innerHTML = socials.filter(s => s.id && s.href).map(s => {
    let iconHtml;
    if (s.iconFile) {
      iconHtml = `<img src="${s.iconFile}" alt="${s.label}" style="width:22px;height:22px;object-fit:contain">`;
    } else {
      iconHtml = _SOCIAL_ICONS[s.iconType] || '';
    }
    const target = s.target ? ` target="${s.target}" rel="noopener"` : '';
    return `<a class="contact-icon-btn" href="${s.href}"${target} title="${s.title||s.label}" aria-label="${s.label}">${iconHtml}</a>`;
  }).join('');
}

function renderSkills(skills) {
  const el = document.querySelector('.skills-layout');
  if (!el) return;
  const groups = {};
  skills.forEach(s => {
    if (!groups[s.category]) groups[s.category] = [];
    groups[s.category].push(s);
  });
  const R = 26, C = +(2 * Math.PI * R).toFixed(3); // r=26 → circ≈163.36, fat ring
  el.innerHTML = Object.entries(groups).map(([cat, items]) => `
    <div class="skill-group">
      <div class="skill-cat-title">${cat}</div>
      <div class="skill-circles">
        ${items.map(s => {
          const off = +(C * (1 - s.level / 100)).toFixed(2);
          const raw = s.icon || _SKILL_ICON_FALLBACK[s.id] || s.abbr;
          let iconHtml;
          if (typeof raw === 'object') {
            iconHtml = `<span class="skill-icon-brand" style="--brand:${raw.color}">${raw.abbr}</span>`;
          } else if (String(raw).startsWith('http') || String(raw).startsWith('data/')) {
            iconHtml = `<img class="skill-icon-img" src="${raw}" alt="${s.name}">`;
          } else {
            iconHtml = `<span class="skill-icon-emoji">${raw}</span>`;
          }
          return `<div class="skill-item">
            <div class="skill-ring-wrap">
              <svg class="skill-ring-svg" viewBox="0 0 68 68" width="68" height="68">
                <circle class="skill-track" cx="34" cy="34" r="${R}" fill="none" stroke-width="6"/>
                <circle class="skill-progress" cx="34" cy="34" r="${R}" fill="none"
                  stroke-width="6" stroke-linecap="round"
                  stroke-dasharray="${C}" stroke-dashoffset="${off}"
                  transform="rotate(-90 34 34)"/>
              </svg>
              <div class="skill-icon"${s.iconColor?` style="background:${s.iconColor};border-radius:6px;padding:3px"`:``}>${iconHtml}</div>
            </div>
            <div class="skill-label">${s.name}</div>
          </div>`;
        }).join('')}
      </div>
    </div>`).join('');
}

