// ── Card parallax & zoom ──────────────────────────────────────────────────────
;(function () {
  const LERP    = 0.06
  const H_SCALE = 1.05
  const H_PUSH  = 5
  const H_PAR   = 0.025

  let items = []
  let rafId = null
  let gridActive = false

  function lerp(a, b, t) { return a + (b - a) * t }
  function refreshRects() { items.forEach(c => { c.r = c.el.getBoundingClientRect() }) }

  function tick() {
    let moving = false
    items.forEach(c => {
      c.tx  = lerp(c.tx,  c.ttx,  LERP)
      c.ty  = lerp(c.ty,  c.tty,  LERP)
      c.sc  = lerp(c.sc,  c.tsc,  LERP)
      c.itx = lerp(c.itx, c.titx, LERP)
      c.ity = lerp(c.ity, c.tity, LERP)
      c.el.style.transform = `translate(${c.tx.toFixed(2)}px,${c.ty.toFixed(2)}px) scale(${c.sc.toFixed(4)})`
      if (c.img) c.img.style.transform = `translate(${c.itx.toFixed(2)}px,${c.ity.toFixed(2)}px) scale(1.1)`
      if (Math.abs(c.sc-c.tsc)+Math.abs(c.tx-c.ttx)+Math.abs(c.ty-c.tty)+Math.abs(c.itx-c.titx)+Math.abs(c.ity-c.tity) > 0.04) moving = true
    })
    rafId = (moving || gridActive) ? requestAnimationFrame(tick) : null
  }

  function onMove(e) {
    const mx = e.clientX, my = e.clientY
    items.forEach(c => {
      const r = c.r
      const inCard = mx >= r.left && mx <= r.right && my >= r.top && my <= r.bottom
      if (inCard) {
        const nx = (mx - (r.left + r.width  * 0.5)) / (r.width  * 0.5)
        const ny = (my - (r.top  + r.height * 0.5)) / (r.height * 0.5)
        c.ttx = -nx * H_PUSH;  c.tty = -ny * H_PUSH
        c.tsc = H_SCALE
        c.titx = nx * r.width * H_PAR;  c.tity = ny * r.height * H_PAR
      } else {
        c.ttx = 0; c.tty = 0; c.tsc = 1; c.titx = 0; c.tity = 0
      }
    })
    if (!rafId) rafId = requestAnimationFrame(tick)
  }

  function onLeave() {
    gridActive = false
    items.forEach(c => { c.ttx = 0; c.tty = 0; c.tsc = 1; c.titx = 0; c.tity = 0 })
    if (!rafId) rafId = requestAnimationFrame(tick)
  }

  window.initCardParallax = function () {
    const grid = document.getElementById('projects-grid')
    if (!grid) return
    items = [...grid.querySelectorAll('.project-card')].map(el => {
      const img = el.querySelector('.project-thumb')
      if (img) img.style.transform = 'translate(0px,0px) scale(1.1)'
      return {
        el, img,
        tx: 0, ty: 0, sc: 1, itx: 0, ity: 0,
        ttx: 0, tty: 0, tsc: 1, titx: 0, tity: 0,
        r: el.getBoundingClientRect()
      }
    })
    grid.onmousemove  = onMove
    grid.onmouseleave = onLeave
    grid.onmouseenter = () => { gridActive = true; refreshRects() }
    window.addEventListener('resize', refreshRects, { passive: true })
    window.addEventListener('scroll', refreshRects, { passive: true })
  }
})()

// ── THEME ─────────────────────────────────────────────────────────────────────
function toggleTheme() {
  const isDark = document.documentElement.classList.toggle('dark');
  localStorage.setItem('pf-theme', isDark ? 'dark' : 'light');
  const chk = document.getElementById('theme-toggle-chk');
  if (chk) chk.checked = isDark;
}

window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => {
  if (!localStorage.getItem('pf-theme')) {
    document.documentElement.classList.toggle('dark', e.matches);
    const chk = document.getElementById('theme-toggle-chk');
    if (chk) chk.checked = e.matches;
  }
});

window.addEventListener('DOMContentLoaded', () => {
  const chk = document.getElementById('theme-toggle-chk');
  if (chk) chk.checked = document.documentElement.classList.contains('dark');

  const lbStage = document.getElementById('lb-stage');
  if (lbStage) {
    lbStage.addEventListener('wheel',      _lbOnWheel,      { passive: false });
    lbStage.addEventListener('mousedown',  _lbOnMouseDown);
    lbStage.addEventListener('touchstart', _lbOnTouchStart, { passive: false });
    lbStage.addEventListener('touchmove',  _lbOnTouchMove,  { passive: false });
    lbStage.addEventListener('touchend',   _lbOnTouchEnd);
  }
  document.addEventListener('mousemove', _lbOnMouseMove);
  document.addEventListener('mouseup',   _lbOnMouseUp);

  const waveCanvas = document.getElementById('wave-hero');
  if (waveCanvas && window.WaveEffect) {
    WaveEffect.init(waveCanvas, {
      baseY:     0.62,
      colorTop:  'rgba(110,60,175,0.90)',
      colorBot:  'rgba(18,6,38,1)',
      wind:      1.0,
      flowSpeed: 0.6
    });
  }

  if (window.PORTFOLIO_DATA) {
    const { projects: _pd, career: _cd, skills: _sd, socials: _so, siteContent: _sc } = window.PORTFOLIO_DATA;
    renderProjects(_pd.filter(p => p.visible !== false));
    renderCareer(_cd, _pd);
    if (_sd) renderSkills(_sd.filter(s => s.visible !== false));
    if (_so) renderSocials(_so);
    if (_sc) applySiteContent(_sc);
    initCardParallax();
  }
  renderFilterBar();
  applyFocusProfile();
  filterByView('all', document.querySelector('.filter-btn'));

  const _pfModal = sessionStorage.getItem('pf_modal');
  if (_pfModal) {
    const _pfParent = _pfModal.includes('__') ? _pfModal.split('__')[0] : _pfModal;
    if (PROJECTS[_pfParent]) {
      const _pfPsy = parseInt(sessionStorage.getItem('pf_page_sy') || '0', 10);
      const _pfMsy = parseInt(sessionStorage.getItem('pf_modal_sy') || '0', 10);
      window.scrollTo(0, _pfPsy);
      openModal(_pfModal);
      if (_pfMsy > 0) requestAnimationFrame(() => requestAnimationFrame(() => {
        const _sc = document.getElementById('modal-sec-content');
        if (_sc) _sc.scrollTop = _pfMsy;
      }));
    } else {
      sessionStorage.removeItem('pf_modal');
      sessionStorage.removeItem('pf_page_sy');
      sessionStorage.removeItem('pf_modal_sy');
    }
  }
});

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') { closeModalBtn(); closeLightbox(); }
  if (document.getElementById('lightbox')?.classList.contains('open')) {
    if (e.key === '+' || e.key === '=') { e.preventDefault(); _lbZoomStep(1); }
    if (e.key === '-')                  { e.preventDefault(); _lbZoomStep(-1); }
    if (e.key === '0')                  { e.preventDefault(); _lbFit(); }
    if (e.key === '1')                  { e.preventDefault(); _lbZoom1x(); }
  }
  if (document.getElementById('modal-overlay')?.classList.contains('open')) {
    if (e.key === 'ArrowLeft')  { e.preventDefault(); modalNav(-1); }
    if (e.key === 'ArrowRight') { e.preventDefault(); modalNav(1); }
    if (e.key === 'ArrowUp')    { e.preventDefault(); navSection(-1); }
    if (e.key === 'ArrowDown')  { e.preventDefault(); navSection(1); }
  }
});
